namespace Capstone.Game.CaptureSystem {
    /// <summary>Editor-only repeatable verification. No fixtures, writes or hooks in player builds.</summary>
    public sealed class CaptureVerification:MonoBehaviour {
        const string Root=QaArtifactPaths.Root+"capture-stats-visibility-2026-11-04/",Session="Capstone.CaptureVerification";
        const BindingFlags Any=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
        static readonly List<string> checks=new List<string>();static bool running;
        static void Write(string file,string text){Directory.CreateDirectory(Root);File.WriteAllText(Root+file,text);File.AppendAllText(Root+"owned-paths.txt",Root+file+"\n");}
        static void Check(bool pass,string message){checks.Add((pass?"PASS ":"FAIL ")+message);Write("checks.txt",string.Join("\n",checks));if(!pass)throw new Exception(message);}
        static void Set(object instance,string name,object value)=>instance.GetType().GetField(name,Any).SetValue(instance,value);
        sealed class FixedRandom:ICaptureRandom {readonly double value;public int Calls;public FixedRandom(double value){this.value=value;}public double NextFloat01(){Calls++;return value;}}
        sealed class ScriptRandom:ICaptureRandom {readonly double[] values;int i;public ScriptRandom(params double[] values){this.values=values;}public double NextFloat01()=>values[Math.Min(i++,values.Length-1)];}
        [MenuItem("Tools/Capstone/Capture/Verify capture math")]
        public static void VerifyMath(){checks.Clear();try{MathChecks();Write("math-status.txt","COMPLETE "+checks.Count);}catch(Exception e){Write("math-status.txt","FAILED "+e);Debug.LogException(e);}}
        [MenuItem("Tools/Capstone/Capture/Verify isolated capture runtime")]
        public static void VerifyRuntime(){
            if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)return;
            SessionState.SetString(Session+"save",Root+"test-saves/"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff"));Write("save-root.txt",SessionState.GetString(Session+"save",""));SessionState.SetBool(Session,true);SessionState.SetBool(Session+"enabled",EditorSettings.enterPlayModeOptionsEnabled);SessionState.SetInt(Session+"options",(int)EditorSettings.enterPlayModeOptions);EditorSettings.enterPlayModeOptionsEnabled=true;EditorSettings.enterPlayModeOptions=EnterPlayModeOptions.DisableDomainReload;EditorApplication.EnterPlaymode();
        }
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Boot(){if(!SessionState.GetBool(Session,false))return;
            foreach(var s in Object.FindObjectsByType<PlayerSaveController>(FindObjectsInactive.Include,FindObjectsSortMode.None))s.SetSaveStore(new PlayerJsonFileSaveStore(SessionState.GetString(Session+"save",Root+"test-saves")));
            foreach(var s in Object.FindObjectsByType<QuestSaveController>(FindObjectsInactive.Include,FindObjectsSortMode.None))s.SetSaveStore(new QuestJsonFileSaveStore(SessionState.GetString(Session+"save",Root+"test-saves")));
            new GameObject("Isolated capture verification",typeof(CaptureVerification)){hideFlags=HideFlags.DontSave};
        }
        static void MathChecks(){
            var samples=new[]{(100,45,1d,1d,15d,.11944),(20,45,1d,1d,39d,.24460),(20,45,2d,1d,78d,.41130),(20,45,2d,2.5,195d,.81780),(100,255,1d,1d,85d,.43870),(1,255,1d,1d,253.3,.99500)};
            var csv=new List<string>{"hp,baseRate,ball,status,modifiedRate,theory,observed,trials,tolerance"};
            foreach(var s in samples){var c=new CaptureContext(s.Item1,100,s.Item2,new CaptureBallRules(s.Item3),s.Item4==2.5?CaptureMajorStatus.Asleep:CaptureMajorStatus.None);Check(CaptureCalculator.TryOdds(c,out var odds,out _),"sample valid "+s);
                Check(Math.Abs(odds.ModifiedRate-s.Item5)<.00001&&Math.Abs(odds.NormalChance-s.Item6)<.0001,"formula reference "+s);
                const int n=100000;int caught=0;var random=new SeededCaptureRandom(713+s.Item1+s.Item2+(int)(s.Item3*10));for(int i=0;i<n;i++){CaptureCalculator.TryRoll(c,random,out var roll,out _);if(roll.Success)caught++;}
                double measured=caught/(double)n,tolerance=Math.Max(.005,4*Math.Sqrt(odds.NormalChance*(1-odds.NormalChance)/n));Check(Math.Abs(measured-odds.NormalChance)<=tolerance,"100000 seeded throws "+s);
                csv.Add(FormattableString.Invariant($"{s.Item1},{s.Item2},{s.Item3},{s.Item4},{odds.ModifiedRate},{odds.NormalChance},{measured},{n},{tolerance}"));
            }Write("monte-carlo.csv",string.Join("\n",csv));
            foreach(CaptureMajorStatus status in Enum.GetValues(typeof(CaptureMajorStatus))){var c=new CaptureContext(20,100,45,new CaptureBallRules(1),status);CaptureCalculator.TryOdds(c,out var o,out _);double factor=status==CaptureMajorStatus.None?1:status==CaptureMajorStatus.Asleep||status==CaptureMajorStatus.Frozen?2.5:1.5;Check(Math.Abs(o.ModifiedRate-39*factor)<.00001,"one major status "+status);}
            var invalid=new[]{new CaptureContext(0,100,255,new CaptureBallRules(1,true)),new CaptureContext(100,0,45,new CaptureBallRules(1)),new CaptureContext(101,100,45,new CaptureBallRules(1)),new CaptureContext(double.NaN,100,45,new CaptureBallRules(1)),new CaptureContext(1,double.PositiveInfinity,45,new CaptureBallRules(1)),new CaptureContext(1,100,0,new CaptureBallRules(1)),new CaptureContext(1,100,256,new CaptureBallRules(1)),new CaptureContext(1,100,45,new CaptureBallRules(0)),new CaptureContext(1,100,45,new CaptureBallRules(-1)),new CaptureContext(1,100,45,new CaptureBallRules(double.NaN)),new CaptureContext(1,100,45,new CaptureBallRules(double.PositiveInfinity)),new CaptureContext(1,100,45,new CaptureBallRules(1,true),allowed:false)};
            foreach(var c in invalid){var r=new FixedRandom(0);Check(!CaptureCalculator.TryRoll(c,r,out _,out _)&&r.Calls==0,"invalid context rejected before RNG "+checks.Count);}
            foreach(int rate in new[]{1,255})foreach(int hp in new[]{1,100})Check(CaptureCalculator.TryOdds(new CaptureContext(hp,100,rate,new CaptureBallRules(1)),out _,out _),"rate and HP boundary "+rate+"/"+hp);
            for(int fail=0;fail<4;fail++){var draws=Enumerable.Repeat(0d,fail).Concat(new[]{.999999}).ToArray();CaptureCalculator.TryRoll(new CaptureContext(100,100,45,new CaptureBallRules(1)),new ScriptRandom(draws),out var r,out _);Check(!r.Success&&r.ShakeCount==fail,"shake mapping failure "+fail);}
            var four=new FixedRandom(0);CaptureCalculator.TryRoll(new CaptureContext(100,100,45,new CaptureBallRules(1)),four,out var passed,out _);Check(passed.Success&&passed.ShakeCount==3&&four.Calls==4,"normal four checks once");
            foreach(var c in new[]{new CaptureContext(1,100,255,new CaptureBallRules(2)),new CaptureContext(100,100,1,new CaptureBallRules(1,true))}){var r=new FixedRandom(1);CaptureCalculator.TryRoll(c,r,out var result,out _);Check(result.Success&&r.Calls==0,"guaranteed only after validation");}
            Check(!CaptureCalculator.TryOdds(new CaptureContext(20,100,45,new CaptureBallRules(1,false,CaptureBallCondition.Quick)),out _,out var why)&&why==CaptureFailure.TurnUnavailable,"no fabricated realtime turn");
            foreach(var tuple in new[]{(CaptureBallCondition.Quick,1,5d),(CaptureBallCondition.Quick,2,1d),(CaptureBallCondition.Timer,1,1d),(CaptureBallCondition.Timer,11,4d)}){CaptureCalculator.TryOdds(new CaptureContext(100,100,1,new CaptureBallRules(1,false,tuple.Item1),battleTurnIndex:tuple.Item2),out var o,out _);Check(Math.Abs(o.ModifiedRate*3-tuple.Item3)<.000001,"conditional ball math "+tuple);}
            CaptureCalculator.TryOdds(new CaptureContext(20,100,45,new CaptureBallRules(1),enableCritical:true,caughtUniqueSpeciesCount:30),out var low,out _);Check(low.CriticalChance==0,"low unique dex has no critical");
            CaptureCalculator.TryRoll(new CaptureContext(20,100,45,new CaptureBallRules(1),enableCritical:true,caughtUniqueSpeciesCount:601),new FixedRandom(0),out var critical,out _);Check(critical.Success&&critical.IsCritical&&critical.ShakeCount==1,"optional critical one check");
            var save=new PlayerSaveData();string v12=PlayerSaveMigration.Write(save).Replace("\"version\": 13","\"version\": 12");var migrated=PlayerSaveMigration.Read(v12,out int version);Check(version==12&&migrated.version==13,"v12 read migration remains compatible");
            var ball=CaptureAssets.LoadBall();Check(ball!=null&&ball.IsCaptureBall&&ball.CaptureRules.Multiplier==1&&!ball.CaptureRules.Guaranteed,"authored one basic ball x1");
            foreach(var name in new[]{"DragonDusk","DragonDuskWinged","DragonDuskElder"}){var p=Resources.Load<PetStatProfile>("PetStats/"+name);int expected=name=="DragonDusk"?255:name=="DragonDuskWinged"?120:45;Check(p!=null&&p.IsCatchable&&p.BaseCatchRate==expected,"independent authored catch data "+name);}
            Write("math-checks.txt",string.Join("\n",checks));
        }
        static WildPetCaptureTarget Wild(string form,Vector3 position){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/CaptureSystem/Prefabs/WildDragon"+form+".prefab");var go=Object.Instantiate(prefab,position,Quaternion.identity);go.name="QA Wild Dragon "+form;return go.GetComponent<WildPetCaptureTarget>();}
        static void Click(Button button){Check(button!=null&&button.enabledInHierarchy,"enabled button "+button?.name);typeof(Clickable).GetMethod("Invoke",Any).Invoke(button.clickable,new object[]{null});}
        static async Task Gap(int ms=220)=>await Task.Delay(ms);
        static async Task Shot(string name){string path=Root+name+".png";File.AppendAllText(Root+"owned-paths.txt",path+"\n");ScreenCapture.CaptureScreenshot(path);await Gap(200);}
        async void Start(){running=true;checks.Clear();Write("runtime-status.txt","RUNNING "+DateTime.Now);EditorWindow view=null;PropertyInfo size=null;int oldSize=-1;MonsterInventoryController bag=null;CapturePresentation visual=null;
            try{
                await Gap(1600);MathChecks();
                var saves=Object.FindFirstObjectByType<PlayerSaveController>();var roster=Object.FindFirstObjectByType<PetBoxRuntimeProvider>();var command=Object.FindFirstObjectByType<PetCommandInput>();var coordinator=Object.FindFirstObjectByType<PetCaptureCoordinator>();var inventory=Object.FindFirstObjectByType<MonsterInventoryAdapter>();bag=Object.FindFirstObjectByType<MonsterInventoryController>();var menu=Object.FindFirstObjectByType<GameMenuController>();var camera=Object.FindFirstObjectByType<BasicCameraFollow>();
                Check(saves.SavePath.StartsWith(Root),"isolated player save on E");Check(!saves.IsSaveBlocked,"test save can load");
                var ball=CaptureAssets.LoadBall();inventory.TryAddItemAtomic(ball,30);command.petSlots=new PetController[6];command.activePet=null;roster.Bind(command);roster.RestoreState(Array.Empty<PetController>(),1);
                var target=Wild("01",command.transform.position+command.transform.forward*4);await Gap();Check(target.IsWild&&target.Enemy.IsAlive&&target.GetComponentsInChildren<Renderer>().Any(r=>r.enabled),"wild prefab visible, same actor target");
                var before=target.Metadata.CreateSaveData();float hp=target.Stats.Health;var ids=target.Stats.GetSkills().Select(s=>s.skillId).ToArray();string id=target.Metadata.PersistentId;int qty=inventory.GetQuantity(ball);int committed=0;
                coordinator.CaptureCommitted+=pet=>{committed++;var persisted=PlayerSaveMigration.Read(File.ReadAllText(saves.SavePath),out _);string key=pet.GetComponentInChildren<PetCollectionMetadata>().PersistentId;Check(persisted.pets.petStates.Any(p=>p.petId==key&&p.customization.captureBallId=="capture-ball-basic-01"),"capture event occurs after persisted individual data");};
                coordinator.RandomSource=new FixedRandom(.999999);Check(coordinator.TryCaptureTarget(ball,inventory,target,out var miss,out _)&&!miss.Success,"valid failed throw");Check(inventory.GetQuantity(ball)==qty-1&&target.IsWild&&!roster.Contains(target.Pet),"failure consumes exactly one and keeps target wild");
                Check(!File.ReadAllText(saves.SavePath).Contains(id),"unowned wild instance excluded from save");
                coordinator.RandomSource=new FixedRandom(0);qty=inventory.GetQuantity(ball);Check(coordinator.TryCaptureTarget(ball,inventory,target,out var caught,out string error)&&caught.Success,"capture succeeds "+error);Check(command.petSlots[0]==target.Pet&&roster.StoredCount==0,"first free party slot before BOX");
                Check(inventory.GetQuantity(ball)==qty-1&&committed==1,"one consumption and one success event");Check(target.Metadata.PersistentId==id&&target.Metadata.CaptureBallId==ball.StableId,"same persistent actor and ball id");
                Check(JsonUtility.ToJson(before.individualValues)==JsonUtility.ToJson(target.Metadata.IndividualValues)&&before.nature==target.Metadata.Nature&&JsonUtility.ToJson(before.effortValues)==JsonUtility.ToJson(target.Metadata.EffortValues),"capture keeps IV EV nature");Check(target.Stats.Health==hp&&target.Stats.GetSkills().Select(s=>s.skillId).SequenceEqual(ids),"capture preserves HP and equipped skills");
                qty=inventory.GetQuantity(ball);Check(!coordinator.TryCaptureTarget(ball,inventory,target,out _,out _)&&inventory.GetQuantity(ball)==qty&&committed==1,"duplicate capture is rejected without consumption");
                var catalog=AssetDatabase.LoadAssetAtPath<PetPrefabCatalog>("Assets/Game/HudSystem/Prefabs/DragonEvolutionCatalog.asset");
                for(int i=1;i<6;i++){catalog.TryInstantiate("Dragon Dusk","01",null,out var filler);filler.GetComponentInChildren<PetCollectionMetadata>().AssignPersistentId("qa-party-"+i+"-"+Guid.NewGuid().ToString("N"));command.petSlots[i]=filler;}
                var boxTarget=Wild("02",command.transform.position+Vector3.right*4);await Gap();Check(coordinator.TryCaptureTarget(ball,inventory,boxTarget,out var boxResult,out _)&&boxResult.Success&&roster.GetStoredPet(0)==boxTarget.Pet,"party six routes exact target to BOX");
                var third=Wild("03",command.transform.position+Vector3.left*4);await Gap();qty=inventory.GetQuantity(ball);var noRoll=new FixedRandom(0);coordinator.RandomSource=noRoll;Check(!coordinator.TryCaptureTarget(ball,inventory,third,out _,out _)&&inventory.GetQuantity(ball)==qty&&noRoll.Calls==0,"full party and BOX reject before item/RNG");
                roster.RestoreState(Array.Empty<PetController>(),1);Check(saves.SaveNow(),"save fixture before fault test");
                var savedSlots=inventory.CaptureSlots();inventory.TryRemoveItemAtomic(ball,inventory.GetQuantity(ball));Check(!coordinator.TryCaptureTarget(ball,inventory,third,out _,out _)&&inventory.GetQuantity(ball)==0,"zero inventory cannot throw");inventory.RestoreCaptureSlots(savedSlots);qty=inventory.GetQuantity(ball);int eventsBefore=committed;byte[] savedBefore=File.ReadAllBytes(saves.SavePath);string thirdBefore=JsonUtility.ToJson(third.Metadata.CreateSaveData());
                using(var locked=new FileStream(saves.SavePath,FileMode.Open,FileAccess.Read,FileShare.None))Check(!coordinator.TryCaptureTarget(ball,inventory,third,out _,out _),"real file IO failure rejects transaction");
                Check(inventory.GetQuantity(ball)==qty&&!roster.Contains(third.Pet)&&third.IsWild&&committed==eventsBefore,"save failure rolls back item roster and event");Check(File.ReadAllBytes(saves.SavePath).SequenceEqual(savedBefore)&&JsonUtility.ToJson(third.Metadata.CreateSaveData())==thirdBefore,"save failure preserves previous file and individual");Check(saves.LoadNow(),"recover test save after intentional IO failure");
                third.Enemy.isBoss=true;qty=inventory.GetQuantity(ball);Check(!coordinator.TryCaptureTarget(ball,inventory,third,out _,out _)&&inventory.GetQuantity(ball)==qty,"boss protected");third.Enemy.isBoss=false;
                third.Enemy.InitializeCaptureHealth(0,third.Enemy.maxHealth);Check(!coordinator.TryCaptureTarget(ball,inventory,third,out _,out _)&&inventory.GetQuantity(ball)==qty,"KO cannot consume a ball");third.Enemy.InitializeCaptureHealth(third.Stats.Health,third.Stats.MaxHealth);
                var loaded=PlayerSaveMigration.Read(File.ReadAllText(saves.SavePath),out _);Check(loaded.pets.petStates.Count(p=>p.petId==id)==1&&loaded.pets.petStates.Find(p=>p.petId==id).customization.captureBallId==ball.StableId,"save/load ball id and no duplicated captured actor");
                var previousActor=command.petSlots[0];Object.Destroy(previousActor.gameObject);command.petSlots[0]=null;command.activePet=null;await Gap();Check(saves.LoadNow(),"load reconstructs missing captured actor from existing catalog");Check(command.petSlots[0]!=null&&command.petSlots[0]!=previousActor&&command.petSlots[0].GetComponentInChildren<PetCollectionMetadata>().PersistentId==id&&command.petSlots[0].GetComponentInChildren<PetCollectionMetadata>().CaptureBallId==ball.StableId,"restored actor keeps individual id and capture ball");
                var ui=bag.GetComponent<UIDocument>().rootVisualElement;var gameType=typeof(UnityEditor.Editor).Assembly.GetType("UnityEditor.GameView");view=EditorWindow.GetWindow(gameType);size=gameType.GetProperty("selectedSizeIndex",Any);oldSize=(int)size.GetValue(view);view.Show();view.Focus();
                foreach(var resolution in new[]{new Vector2Int(1920,1080),new Vector2Int(1366,768)}){
                    var select=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("Capstone.Game.UISystem.Editor.TrainerMenuPolishCapture")).First(t=>t!=null);select.GetMethod("SelectSize",Any).Invoke(null,new object[]{view,size,resolution});await Gap(400);Check(Screen.width==resolution.x&&Screen.height==resolution.y,"actual runtime resolution "+resolution);
                    menu.OpenPetsDirect();await Gap();var party=Object.FindFirstObjectByType<PetPartyPanelController>();party.OpenDetails(command.petSlots[0]);await Gap();var toggle=ui.Q<Button>("pet-details-advanced-toggle");var body=ui.Q("pet-details-advanced-body");Check(body.resolvedStyle.display==DisplayStyle.None,"advanced stats default closed "+resolution);Rect normal=toggle.worldBound;toggle.Focus();await Gap();Check(toggle.worldBound==normal,"advanced toggle focus has zero movement");
                    foreach(float x in new[]{.2f,.5f,.8f})foreach(float y in new[]{.2f,.5f,.8f}){var pick=toggle.panel.Pick(toggle.worldBound.position+new Vector2(toggle.worldBound.width*x,toggle.worldBound.height*y));Check(pick==toggle||toggle.Contains(pick),"advanced full-body hit "+x+","+y);}
                    await Shot("pet-collapsed-"+resolution.x);Click(toggle);await Gap();Check(body.resolvedStyle.display==DisplayStyle.Flex,"advanced actual callback opens");Check(body.worldBound.y>=toggle.worldBound.yMax+5,"advanced content is below header without overlap");var scroll=ui.Q<ScrollView>(className:"ga-details-scroll");scroll.ScrollTo(toggle);await Gap();using(var submit=NavigationSubmitEvent.GetPooled()){submit.target=toggle;toggle.SendEvent(submit);}await Gap();Check(body.resolvedStyle.display==DisplayStyle.None,"keyboard submit toggles advanced once");using(var submit=NavigationSubmitEvent.GetPooled()){submit.target=toggle;toggle.SendEvent(submit);}await Gap();Check(body.resolvedStyle.display==DisplayStyle.Flex,"keyboard submit reopens advanced");await Shot("pet-expanded-"+resolution.x);party.CloseDetails();party.OpenDetails(command.petSlots[0]);Check(body.style.display.value==DisplayStyle.None,"reopen resets advanced");bag.Close();await Gap();
                    var missingObject=new GameObject("QA missing stats");missingObject.SetActive(false);var missingPet=missingObject.AddComponent<PetController>();missingObject.AddComponent<PetCollectionMetadata>().AssignDefinitionId("qa-no-stat-profile");missingObject.SetActive(true);Set(missingPet,"wildEncounter",true);menu.OpenPetsDirect();await Gap();party.OpenDetails(missingPet);await Gap();Check(ui.Q("pet-details-stats-unavailable").resolvedStyle.display==DisplayStyle.Flex&&!ui.Q<Button>("pet-details-advanced-toggle").enabledInHierarchy,"missing profile shows unavailable state without invented stats");party.CloseDetails();Object.Destroy(missingObject);bag.Close();await Gap();menu.OpenInventoryDirect();await Gap();Click(ui.Q<Button>("category-capture-ball"));await Gap();bag.SelectNextItem();await Gap();var button=ui.Q<Button>("use-button");Set(camera,"lockedEnemy",null);typeof(MonsterInventoryController).GetMethod("RefreshActionButtons",Any).Invoke(bag,null);Check(!button.enabledInHierarchy&&!string.IsNullOrWhiteSpace(button.tooltip),"BAG requires target and explains disabled");await Shot("bag-unavailable-"+resolution.x);
                    // A new explicit wild target, selected through the actual camera lock source.
                    var uiTarget=Wild("01",command.transform.position+command.transform.forward*4);await Gap();Set(camera,"lockedEnemy",uiTarget.Enemy);Set(camera,"enemyLockActive",true);typeof(MonsterInventoryController).GetMethod("RefreshActionButtons",Any).Invoke(bag,null);Check(button.enabledInHierarchy&&button.Q<Label>("bag-caption").text=="BẮT THÚ","BAG capture action enabled for locked wild");
                    Rect bounds=button.worldBound;foreach(float x in new[]{.2f,.5f,.8f})foreach(float y in new[]{.2f,.5f,.8f}){var pick=button.panel.Pick(bounds.position+new Vector2(bounds.width*x,bounds.height*y));Check(pick==button||button.Contains(pick),"capture full-body hit "+x+","+y);}
                    await Shot("bag-ready-"+resolution.x);coordinator.RandomSource=new FixedRandom(.999999);if(resolution.x==1920)Click(button);else{using(var submit=NavigationSubmitEvent.GetPooled()){submit.target=button;button.SendEvent(submit);}}await Gap(120);Check(!bag.IsOpen,"BAG click commits and closes for world presentation");visual=coordinator.GetComponent<CapturePresentation>();Check(visual!=null&&visual.IsPlaying&&InventoryInputController.GameplayInputBlocked,"capture presentation owns temporary input block");if(resolution.x==1920)await Shot("capture-presentation-1920");float heldHp=uiTarget.Enemy.CurrentHealth;uiTarget.Enemy.TakeDamage(10);Check(uiTarget.Enemy.CurrentHealth==heldHp,"target damage is held while capture animates");visual.Cancel();Check(!visual.IsPlaying&&!InventoryInputController.GameplayInputBlocked&&!uiTarget.Enemy.CaptureLocked,"cancel animation releases input and target without another roll");
                    var testScene=UnityEngine.SceneManagement.SceneManager.CreateScene("Capture QA transient scene");var transient=new GameObject("Transient capture view",typeof(CapturePresentation));UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(transient,testScene);var sceneView=transient.GetComponent<CapturePresentation>();sceneView.Play(new CapturePresentationResult(new CaptureRoll(false,false,0),uiTarget),command.transform,bag.GetComponent<UIDocument>());await Gap(80);var unloading=UnityEngine.SceneManagement.SceneManager.UnloadSceneAsync(testScene);while(!unloading.isDone)await Gap(20);Check(!InventoryInputController.GameplayInputBlocked,"actual additive scene unload releases capture input ownership");if(resolution.x==1920){await Gap(250);Check(ui.panel.visualTree.Q("capture-target-hud")?.resolvedStyle.display==DisplayStyle.Flex,"target HUD shows live HP/level after input restore");await Shot("target-hud-1920");}
                    Check(ui.Query<Label>().ToList().All(l=>!l.text.Contains("BaseCatchRate")&&!l.text.Contains("ShakeCheckChance")&&!l.text.Contains("FinalCaptureChance")),"no internal capture numbers bound to labels");
                }
                Write("runtime-status.txt","COMPLETE "+checks.Count+" checks. Editor engine events/hit tests; no physical OS input/standalone/Profiler claim.");
            }catch(Exception e){Write("runtime-status.txt","FAILED "+e);Debug.LogException(e);}
            finally{visual?.Cancel();bag?.Close();if(view!=null&&oldSize>=0)size.SetValue(view,oldSize);SessionState.SetBool(Session,false);running=false;EditorApplication.ExitPlaymode();EditorApplication.delayCall+=()=>{EditorSettings.enterPlayModeOptionsEnabled=SessionState.GetBool(Session+"enabled",false);EditorSettings.enterPlayModeOptions=(EnterPlayModeOptions)SessionState.GetInt(Session+"options",0);};}
        }
    }
